#pragma once

#include <QByteArray>
#include <QIconEngine>
#include <QString>

namespace pdfe::ui {

/// Renders a monochrome toolbar SVG in the CURRENT application palette's
/// text colour, so the action icons stay legible under the dark theme.
///
/// The action SVGs (src/ui/icons/action_*.svg, generated by
/// make_action_icons.py) draw every stroke and fill as `currentColor`. They
/// used to hard-code #303030, which is dark grey on the dark theme's #353535
/// toolbar -- a contrast ratio of about 1.1:1. This engine substitutes the
/// palette colour for `currentColor` each time a pixmap is requested:
///
///   Normal / Active  -> QPalette::Active   ButtonText
///   Disabled         -> QPalette::Disabled ButtonText
///   Selected         -> QPalette::Active   HighlightedText
///
/// The colour is read at paint time, never at construction, so an icon set
/// once follows a later Light/Dark/System switch without being re-set. The
/// pixmap cache key includes the colour, so a palette change can never be
/// answered from a pixmap rendered for the previous palette.
class PaletteIconEngine : public QIconEngine {
public:
    /// @p resourcePath is a Qt resource or file path to the SVG source.
    explicit PaletteIconEngine(const QString& resourcePath);

    void paint(QPainter* painter, const QRect& rect, QIcon::Mode mode,
               QIcon::State state) override;
    QPixmap pixmap(const QSize& size, QIcon::Mode mode, QIcon::State state) override;
    QPixmap scaledPixmap(const QSize& size, QIcon::Mode mode, QIcon::State state,
                         qreal scale) override;
    QSize actualSize(const QSize& size, QIcon::Mode mode, QIcon::State state) override;
    QIconEngine* clone() const override;
    QString key() const override;
    bool isNull() override;

    /// The colour an icon in @p mode is drawn with under the current
    /// application palette. Exposed for tests.
    static QColor inkColorFor(QIcon::Mode mode);

    /// Convenience: a QIcon backed by a PaletteIconEngine for @p resourcePath.
    static QIcon icon(const QString& resourcePath);

private:
    QString path_;
    QByteArray svg_;   // source bytes, loaded once
    bool valid_ = false;
};

} // namespace pdfe::ui
